return-response.set-body:
@{
                var subId = context.Request.OriginalUrl.Query.GetValueOrDefault("subscriptionId", "");
                var raw   = context.Variables.ContainsKey("usageData") && context.Variables["usageData"] != null
                    ? (string)context.Variables["usageData"]
                    : "{}";
                var data = JObject.Parse(raw);
                var arr  = new JArray();
                foreach (var prop in data.Properties()) {
                    var m = (JObject)prop.Value;
                    arr.Add(new JObject(
                        new JProperty("model",      prop.Name),
                        new JProperty("tokensUsed", m["used"]?.Value<long>()  ?? 0),
                        new JProperty("tokenLimit", m["limit"]?.Value<long>() ?? 0)
                    ));
                }
                return new JObject(
                    new JProperty("subscriptionId", subId),
                    new JProperty("models", arr)
                ).ToString();
            }
